  'minimax-m3.1',
  'mimo-v2.6-flash-free',
  'mimo-v2.6-flash',
  'mimo-v2.6-pro',
  'mimo-v2.6',
  'mimo-v2.5-pro',
  'mimo-v2.5',
  'muse-spark-1.3',
  'crouton-alpha-free',
  'pulse-alpha-free',
  'flint-40b-free',
  'nemotron-3.5-lightning-free',
  'nemotron-3.5-super-vl-free',
