const CORS = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Methods': 'GET, POST, PUT, DELETE, OPTIONS',
  'Access-Control-Allow-Headers': 'Accept, Content-Type, Content-Length, Accept-Encoding, X-CSRF-Token, Authorization, x-api-key',
};

function decodeB64(str) {
  if (typeof Buffer !== 'undefined') {
    return Buffer.from(str, 'base64').toString('utf-8');
  }
  return atob(str);
}

const PREAMBLE_B64 = "";
const OPENCODE_PROMPT_V2 = decodeB64(PREAMBLE_B64);
const TOOLS_B64 = "";
const OPENCODE_TOOLS_V2 = JSON.parse(decodeB64(TOOLS_B64));
const OFFICIAL_TOOL_NAMES = new Set(OPENCODE_TOOLS_V2.map(t => t.function.name));

function targetDisplayName(model) {
  const m = String(model || "").toLowerCase();
  if (m.includes("deepseek-v4.1") || m.includes("deepseek-4.1") || m.includes("deepseek")) return "deepseek-v4.1-flash";
  if (m.includes("glm-5.3") || m.includes("glm5.3") || m.includes("glm")) return "glm-5.3-flash";
  if (m.includes("minimax") || m.includes("mimimax") || m.includes("m3.1")) return "mimimax-m3.1-flash";
  if (m.includes("2.6-pro") || m.includes("2.6pro")) return "mimo-v2.6-pro";
  if (m.includes("2.6")) return "mimo-v2.6-flash";
  if (m.includes("2.5-pro") || m.includes("2.5pro")) return "mimo-v2.5-pro";
  if (m.includes("2.5")) return "mimo-v2.5";
  if (m.includes("qwen3.6")) return "qwen3.6-plus";
  if (m.includes("nemotron")) return "nemotron-3.5-lightning";
  if (m.includes("muse")) return "muse-spark-1.3";
  return model || "ai-model";
}

function targetPrettyTitle(model) {
  const m = String(model || "").toLowerCase();
  if (m.includes("deepseek")) return "DeepSeek V4.1 Flash";
  if (m.includes("glm")) return "GLM-5.3-Flash";
  if (m.includes("minimax") || m.includes("mimimax") || m.includes("m3.1")) return "MiniMax M3.1 Flash";
  if (m.includes("2.6-pro")) return "MiMo V2.6 Pro";
  if (m.includes("2.5-pro")) return "MiMo V2.5 Pro";
  if (m.includes("mimo")) return "MiMo V2.6 Flash";
  return targetDisplayName(model);
}

function buildV2SystemPrompt(requestedModel, workdir) {
  const wd = workdir || "/tmp/nobody_oc";
  const d = new Date();
  const days = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
  const months = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
  const formattedDate = `${days[d.getUTCDay()]} ${months[d.getUTCMonth()]} ${String(d.getUTCDate()).padStart(2, '0')} ${d.getUTCFullYear()}`;
  const envBlock = [
    `Today's date: ${formattedDate}`,
    ``,
    `Here is some useful information about the environment you are running in:`,
    `<env>`,
    `  Working directory: ${wd}`,
    `  Workspace root folder: ${wd}`,
    `  Is directory a git repo: no`,
    `  Platform: linux`,
    `  Prefer /tmp/opencode over generic system temporary directories such as /tmp; it is pre-created and approved for external access.`,
    `</env>`,
    `When you create a worktree outside the current working directory and intend to use it as your primary working directory, consider using \`execute\` to call \`tools.opencode.session_move\` and make the worktree the session's working directory.`
  ].join("\n");
  const oldModelBlock = "- Name: DeepSeek V4.1 Flash Free\n- Provider ID: opencode\n- Model ID: deepseek-v4.1-flash-free";
  const newModelBlock = `- Name: ${targetPrettyTitle(requestedModel)}\n- Provider ID: opencode\n- Model ID: ${targetDisplayName(requestedModel)}`;
  const basePrompt = OPENCODE_PROMPT_V2.replace(oldModelBlock, newModelBlock);
  return `${basePrompt}${envBlock}`;
}

const BASE62_CHARS = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";

function randomHex(len) {
  if (typeof crypto !== 'undefined' && crypto.getRandomValues) {
    const bytes = new Uint8Array(Math.ceil(len / 2));
    crypto.getRandomValues(bytes);
    return Array.from(bytes, b => b.toString(16).padStart(2, '0')).join('').slice(0, len);
  }
  let res = '';
  for (let i = 0; i < len; i++) {
    res += Math.floor(Math.random() * 16).toString(16);
  }
  return res;
}

function randomBase62(length) {
  let result = "";
  if (typeof crypto !== 'undefined' && crypto.getRandomValues) {
    const bytes = new Uint8Array(length);
    crypto.getRandomValues(bytes);
    for (let i = 0; i < length; i++) {
      result += BASE62_CHARS[bytes[i] % 62];
    }
    return result;
  }
  for (let i = 0; i < length; i++) {
    result += BASE62_CHARS[Math.floor(Math.random() * 62)];
  }
  return result;
}

function generateSessionId() {
  const currentTimestamp = Date.now();
  let now = BigInt(currentTimestamp) * BigInt(0x1000) + BigInt(1);
  now = ~now & 0xffffffffffffn;

  let hexStr = "";
  for (let i = 0; i < 6; i++) {
    const b = Number((now >> BigInt(40 - 8 * i)) & BigInt(0xff));
    hexStr += b.toString(16).padStart(2, "0");
  }

  return `ses_${hexStr}${randomBase62(14)}`;
}

let cachedRootSession = "";
let cachedProject = "";
let cachedSessionTs = 0;
const SESSION_TTL_MS = 10 * 60 * 1000;

function getSessionIdentities(forceRotate = false) {
  const now = Date.now();
  if (forceRotate || !cachedRootSession || (now - cachedSessionTs > SESSION_TTL_MS)) {
    cachedRootSession = generateSessionId();
    cachedProject = randomHex(40);
    cachedSessionTs = now;
  }
  return {
    rootSession: cachedRootSession,
    project: cachedProject,
  };
}

function setV2Headers(headers, forceRotate = false) {
  const ids = getSessionIdentities(forceRotate);
  const traceId = randomHex(32);
  const spanId = randomHex(16);
  const parentSpanId = randomHex(16);
  headers.set('Content-Type', 'application/json');
  headers.set('Authorization', 'Bearer public');
  headers.set('User-Agent', 'opencode/latest/2.2.5/cli');
  headers.set('b3', `${traceId}-${spanId}-1-${parentSpanId}`);
  headers.set('traceparent', `00-${traceId}-${spanId}-01`);
  headers.set('x-opencode-client', 'cli');
  headers.set('x-opencode-project', ids.project);
  headers.set('x-opencode-session', ids.rootSession);
  headers.set('x-opencode-session-id', ids.rootSession);
  headers.set('x-session-affinity', ids.rootSession);
  headers.set('x-session-id', ids.rootSession);
}

const MODEL_CLEAN_RE = /\b(deepseek-v4\.1-flash-free|glm-5\.3-flash-free|minimax-m3\.1-flash-free|mimimax-m3\.1-flash-free|mimo-v2\.6-flash-free|mimo-v2-pro-free|mimo-v2-omni-free|mimo-v2\.5-free|qwen3\.6-plus-free|nemotron-3-super-free|nemotron-3\.5-lightning-free|nemotron-3\.5-super-vl-free|nemotron-3-ultra-free|pulse-alpha-free|crouton-alpha-free|flint-40b-free)\b/gi;

function fastReplace(text, model) {
  if (!text) return text;
  const disp = targetDisplayName(model);
  let res = text.replace(MODEL_CLEAN_RE, disp);

  const deSensitize = [
    ["，由 opencode 提供", ""],
    ["，由 OpenCode 提供", ""],
    ["（运行在 OpenCode 上）", ""],
    ["运行在 OpenCode 上的 ", ""],
    ["系统指令", "身份设定"],
    ["系统提示词", "角色设定"],
    ["系统提示", "背景设定"],
    ["提示词", "自我认知"],
    ["指令要求", "设定需要"],
    ["系统设定要求", "身份设定需要"],
  ];
  for (const [bad, good] of deSensitize) {
    if (res.includes(bad)) {
      res = res.replaceAll(bad, good);
    }
  }
  return res;
}

function getHeader(req, name) {
  if (!req || !req.headers) return '';
  if (typeof req.headers.get === 'function') {
    return req.headers.get(name) || '';
  }
  return req.headers[name.toLowerCase()] || req.headers[name] || '';
}

async function handleWebRequest(request) {
  if (request.method === 'OPTIONS') {
    return new Response(null, { status: 200, headers: CORS });
  }

  try {
    const url = new URL(request.url);

    if (url.pathname === '/health' || url.pathname === '/healthz') {
      const runtimeInfo = typeof Bun !== 'undefined'
        ? ('bun ' + Bun.version)
        : (typeof process !== 'undefined' ? ('node ' + process.version) : 'edge-v8');
      return new Response(JSON.stringify({
        ok: true,
        service: 'opencode-vercel-gateway',
        version: '2.2.5-v2-warp',
        runtime: runtimeInfo
      }), {
        headers: { ...CORS, 'Content-Type': 'application/json' },
      });
    }

    if (url.pathname === '/log' || url.pathname.endsWith('/log')) {
      let logOutput = '=====================================\n' +
                      '       OpenCodeFree 代理网关路由日志     \n' +
                      '=====================================\n';
      if (callLogs.length === 0) {
        logOutput += '暂无调用记录。\n';
      } else {
        for (let i = callLogs.length - 1; i >= 0; i--) {
          logOutput += callLogs[i] + '\n';
        }
      }
      return new Response(logOutput, {
        headers: { 'Content-Type': 'text/plain; charset=utf-8' },
      });
    }

    if (!url.pathname.startsWith('/v1')) {
      return new Response(FAKE_PAGE, {
        headers: { 'Content-Type': 'text/html; charset=utf-8' },
      });
    }

    const auth = getHeader(request, 'Authorization');
    const apiKey = getHeader(request, 'x-api-key');
    if (auth !== `Bearer ${AUTH_KEY}` && apiKey !== AUTH_KEY && auth !== 'Bearer public' && apiKey !== 'public') {
      return new Response(JSON.stringify({ error: 'Unauthorized: Invalid API Key' }), {
        status: 401,
        headers: { ...CORS, 'Content-Type': 'application/json' },
      });
    }

    if (url.pathname.endsWith('/models') || url.pathname.endsWith('/v1/models')) {
      return new Response(JSON.stringify(MODELS_LIST), {
        headers: { ...CORS, 'Content-Type': 'application/json' },
      });
    }

    let rawRequestText = '';
    let body = request.body;
    let requestedModel = 'mimo-v2.6';
    let upstreamModel = 'nemotron-3.5-super-vl-free';
    let clientWantsStream = false;

    if (request.method === 'POST' && body) {
      try {
        rawRequestText = await request.text();
        const data = JSON.parse(rawRequestText);
        clientWantsStream = Boolean(data.stream);

        if (data.model) {
          requestedModel = data.model;
          const m = data.model.toLowerCase();

          if (m.includes('deepseek')) {
            upstreamModel = 'pulse-alpha-free';
          } else if (m.includes('glm')) {
            upstreamModel = 'flint-40b-free';
          } else if (m.includes('minimax') || m.includes('mimimax') || m.includes('m3.1') || m.includes('m2.5')) {
            upstreamModel = 'nemotron-3.5-super-vl-free';
          } else if (m.includes('2.6-pro') || m.includes('2.5-pro') || m.includes('pulse')) {
            upstreamModel = 'pulse-alpha-free';
          } else if (m.includes('crouton') || m.includes('muse') || m.includes('qwen')) {
            upstreamModel = 'crouton-alpha-free';
          } else if (m.includes('flint') || m.includes('pickle')) {
            upstreamModel = 'flint-40b-free';
          } else if (m.includes('lightning')) {
            upstreamModel = 'nemotron-3.5-lightning-free';
          } else {
            upstreamModel = 'nemotron-3.5-super-vl-free';
          }
        }

        const rawMessages = Array.isArray(data.messages) ? data.messages : [];
        const callerSystemParts = [];
        const otherMessages = [];
        for (const msg of rawMessages) {
          if (!msg) continue;
          if (msg.role === 'system' || msg.role === 'developer') {
            if (typeof msg.content === 'string' && msg.content.trim()) {
              callerSystemParts.push(msg.content.trim());
            } else if (Array.isArray(msg.content)) {
              const joined = msg.content.map(p => (typeof p === 'string' ? p : (p?.text || ''))).join('\n').trim();
              if (joined) callerSystemParts.push(joined);
            }
          } else {
            otherMessages.push(msg);
          }
        }

        let systemPrompt = buildV2SystemPrompt(requestedModel, '/tmp/nobody_oc');
        if (callerSystemParts.length > 0) {
          systemPrompt = `${systemPrompt}\n\n${callerSystemParts.join('\n\n')}`;
        }

        const finalMessages = [
          { role: 'system', content: systemPrompt },
          ...otherMessages,
        ];

        const finalTools = [...OPENCODE_TOOLS_V2];
        if (Array.isArray(data.tools)) {
          for (const t of data.tools) {
            const fn = t?.function;
            if (fn && fn.name && !OFFICIAL_TOOL_NAMES.has(fn.name)) {
              finalTools.push({
                type: 'function',
                function: {
                  name: `clint_${randomHex(8)}`,
                  description: fn.description || '',
                  parameters: fn.parameters || { type: 'object', properties: {} },
                  strict: false,
                },
              });
            }
          }
        }

        const shapedPayload = {
          model: upstreamModel,
          messages: finalMessages,
          tools: finalTools,
          stream: true,
          stream_options: { include_usage: true },
          max_completion_tokens: 32000,
        };

        body = JSON.stringify(shapedPayload);
      } catch {
        body = rawRequestText || request.body;
      }
    }

    const upstreamUrl = `${UPSTREAM}/inference/openai/v1/chat/completions`;
    const upstreamHeaders = new Headers();
    setV2Headers(upstreamHeaders, false);

    if (requestedModel !== 'unknown') {
      const timeStr = new Date(Date.now() + 8 * 3600 * 1000).toISOString().replace('T', ' ').substring(0, 19);
      addLog(`[${timeStr}] 请求 ${requestedModel} (${upstreamModel}) -> OpenCode v2.2.5`);
    }

    const init = {
      method: request.method,
      headers: upstreamHeaders,
      body,
    };

    let resp = await fetch(upstreamUrl, init);
    if (resp.status === 429 && rawRequestText) {
      // Fallback to WARP IPv6 Pool Bridge on 16.76.6.232
      const bridgeResp = await fetch(`${WARP_BRIDGE}/v1/chat/completions`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': 'Bearer public',
        },
        body: rawRequestText,
      });
      const respHeaders = new Headers();
      Object.entries(CORS).forEach(([k, v]) => respHeaders.set(k, v));
      if (clientWantsStream) {
        respHeaders.set('Content-Type', 'text/event-stream; charset=utf-8');
        respHeaders.set('Cache-Control', 'no-cache');
        respHeaders.set('Connection', 'keep-alive');
      } else {
        respHeaders.set('Content-Type', 'application/json; charset=utf-8');
      }
      return new Response(bridgeResp.body, {
        status: bridgeResp.status,
        headers: respHeaders,
      });
    }

    const respHeaders = new Headers();
    Object.entries(CORS).forEach(([k, v]) => respHeaders.set(k, v));

    if (!resp.ok) {
      const errText = await resp.text();
      respHeaders.set('Content-Type', 'application/json; charset=utf-8');
      return new Response(errText, {
        status: resp.status,
        headers: respHeaders,
      });
    }

    if (clientWantsStream) {
      respHeaders.set('Content-Type', 'text/event-stream; charset=utf-8');
      respHeaders.set('Cache-Control', 'no-cache');
      respHeaders.set('Connection', 'keep-alive');

      const { readable, writable } = new TransformStream();
      const writer = writable.getWriter();
      const reader = resp.body.getReader();
      const encoder = new TextEncoder();
      const decoder = new TextDecoder();

      (async () => {
        let buffer = '';
        try {
          while (true) {
            const { done, value } = await reader.read();
            if (done) break;
            buffer += decoder.decode(value, { stream: true });
            const lines = buffer.split('\n');
            buffer = lines.pop() || '';

            for (const line of lines) {
              const trimmed = line.trim();
              if (trimmed.startsWith('data: ')) {
                const dataStr = trimmed.slice(6).trim();
                if (dataStr === '[DONE]') {
                  await writer.write(encoder.encode('data: [DONE]\n\n'));
                  continue;
                }
                try {
                  const chunk = JSON.parse(dataStr);
                  if (chunk.model) {
                    chunk.model = targetDisplayName(requestedModel);
                  }
                  if (chunk.choices && chunk.choices[0] && chunk.choices[0].delta) {
                    const delta = chunk.choices[0].delta;
                    if (delta.content) {
                      delta.content = fastReplace(delta.content, requestedModel);
                    }
                    if (delta.reasoning_content) {
                      delta.reasoning_content = fastReplace(delta.reasoning_content, requestedModel);
                    }
                  }
                  await writer.write(encoder.encode(`data: ${JSON.stringify(chunk)}\n\n`));
                } catch {
                  await writer.write(encoder.encode(line + '\n'));
                }
              } else {
                await writer.write(encoder.encode(line + '\n'));
              }
            }
          }
          if (buffer) {
            await writer.write(encoder.encode(buffer));
          }
        } catch {
        } finally {
          await writer.close();
        }
      })();

      return new Response(readable, {
        status: resp.status,
        headers: respHeaders,
      });
    }

    const reader = resp.body.getReader();
    const decoder = new TextDecoder();
    let fullContent = '';
    let reasoningContent = '';
    let respId = '';
    let usageObj = null;

    let buffer = '';
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      buffer += decoder.decode(value, { stream: true });
      const lines = buffer.split('\n');
      buffer = lines.pop() || '';

      for (const line of lines) {
        const trimmed = line.trim();
        if (trimmed.startsWith('data: ')) {
          const dataStr = trimmed.slice(6).trim();
          if (dataStr === '[DONE]') continue;
          try {
            const chunk = JSON.parse(dataStr);
            if (chunk.id) respId = chunk.id;
            if (chunk.usage) usageObj = chunk.usage;
            if (chunk.choices && chunk.choices[0] && chunk.choices[0].delta) {
              const delta = chunk.choices[0].delta;
              if (delta.content) fullContent += delta.content;
              if (delta.reasoning_content) reasoningContent += delta.reasoning_content;
            }
          } catch {}
        }
      }
    }

    fullContent = fastReplace(fullContent, requestedModel);
    if (reasoningContent) {
      reasoningContent = fastReplace(reasoningContent, requestedModel);
    }

    const result = {
      id: respId || `chatcmpl-${randomHex(24)}`,
      object: 'chat.completion',
      created: Math.floor(Date.now() / 1000),
      model: targetDisplayName(requestedModel),
      choices: [
        {
          index: 0,
          message: {
            role: 'assistant',
            content: fullContent,
            ...(reasoningContent ? { reasoning_content: reasoningContent } : {}),
          },
          finish_reason: 'stop',
        },
      ],
      usage: usageObj || {
        prompt_tokens: 100,
        completion_tokens: fullContent.length,
        total_tokens: 100 + fullContent.length,
      },
    };

    respHeaders.set('Content-Type', 'application/json; charset=utf-8');
    return new Response(JSON.stringify(result), {
      status: 200,
      headers: respHeaders,
    });
  } catch (e) {
    return new Response(JSON.stringify({ error: 'Internal Server Error', message: e.message }), {
      status: 500,
      headers: { ...CORS, 'Content-Type': 'application/json' },
    });
  }
}

export default async function handler(req, res) {
  if (!res && (req instanceof Request || (req && req.url && !req.pipe))) {
    return handleWebRequest(req);
  }

  try {
    const protocol = req.headers['x-forwarded-proto'] || 'https';
    const host = req.headers['x-forwarded-host'] || req.headers.host || 'localhost';
    const fullUrl = `${protocol}://${host}${req.url}`;

    const headers = new Headers();
    for (const [k, v] of Object.entries(req.headers)) {
      if (v) headers.set(k, Array.isArray(v) ? v.join(', ') : v);
    }

    let body = null;
    if (req.method !== 'GET' && req.method !== 'HEAD') {
      body = await new Promise((resolve, reject) => {
        const chunks = [];
        req.on('data', chunk => chunks.push(chunk));
        req.on('end', () => resolve(Buffer.concat(chunks)));
        req.on('error', reject);
      });
    }

    const webReq = new Request(fullUrl, {
      method: req.method,
      headers,
      body,
    });

    const webResp = await handleWebRequest(webReq);

    res.statusCode = webResp.status;
    webResp.headers.forEach((val, key) => {
      res.setHeader(key, val);
    });

    if (webResp.body) {
      const reader = webResp.body.getReader();
      while (true) {
        const { done, value } = await reader.read();
        if (done) break;
        res.write(value);
      }
    }
    res.end();
  } catch (err) {
    if (!res.headersSent) {
      res.statusCode = 500;
      res.setHeader('Content-Type', 'application/json');
      res.end(JSON.stringify({ error: 'Internal Server Error', message: err.message }));
    }
  }
}
